import { MeshStandardNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { } from '@/primitives';
import { } from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Root container
  const root = new Group();
  root.name = config?.name ?? 'stat-tile-feature';
  root.userData = {
    handlers: {},
    cleanup: () => {}
  };

  // Geometry
  const geometry = new PlaneGeometry(2, 2, 64, 64); // size will be scaled later via parent transform
  // Material with placeholders
  const material = new MeshStandardNodeMaterial({
    color: 0xffffff,
    metalness: 0.0,
    roughness: 0.6,
    depthWrite: true
  });

  const plane = new Mesh(geometry, material);
  plane.castShadow = true;
  plane.receiveShadow = true;
  root.add(plane);

  // Load textures asynchronously
  const texturePromises = [];

  if (config.imageUrl) {
    const imgPromise = ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
    texturePromises.push(imgPromise);
  }

  if (config.depthMapUrl) {
    const depthPromise = ctx.textureLoader.loadTexture(config.depthMapUrl).then((tex) => {
      material.displacementMap = tex;
      material.displacementScale = 0.2; // subtle displacement
      material.needsUpdate = true;
    });
    texturePromises.push(depthPromise);
  }

  // Interaction timelines storage
  const timelines = [];

  // Hover rise‑in effect (subtle, 0.15 scene units)
  const hoverEnter = () => {
    const tl = gsap.timeline({ defaults: { duration: 0.7, ease: 'power3.out' } });
    tl.to(plane.position, { y: plane.position.y + 0.15 });
    timelines.push(tl);
  };

  const hoverLeave = () => {
    const tl = gsap.timeline({ defaults: { duration: 0.5, ease: 'power2.in' } });
    tl.to(plane.position, { y: plane.position.y - 0.15 });
    timelines.push(tl);
  };

  // Click emit
  const onClick = () => {
    ctx.emit('hub-features.select');
  };

  // Register handlers
  root.userData.handlers.hoverEnter = hoverEnter;
  root.userData.handlers.hoverLeave = hoverLeave;
  root.userData.handlers.click = onClick;

  // Apply cinematic primitives
  const primitiveInstances = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives[prim.name];
      if (fn) {
        const instance = fn(root, prim.params ?? {});
        primitiveInstances.push(instance);
      }
    }
  }

  // Cleanup implementation
  root.userData.cleanup = () => {
    // kill GSAP timelines
    for (const tl of timelines) {
      tl.kill();
    }
    // dispose primitive resources
    for (const inst of primitiveInstances) {
      if (inst && typeof inst.cleanup === 'function') {
        inst.cleanup();
      }
    }
    // dispose Three.js resources
    if (material.map) material.map.dispose();
    if (material.displacementMap) material.displacementMap.dispose();
    material.dispose();
    geometry.dispose();
  };

  // Ensure cleanup runs after texture promises settle (optional safety)
  Promise.all(texturePromises).catch(() => { /* ignore texture load errors */ });

  return root;
}
